<script lang="ts">
 import {queueDepth} from '$lib/shared/presentation/queue-context';
 import TeamAvatar from './TeamAvatar.svelte';
 import UnsavedChanges from '$lib/shared/presentation/ui/UnsavedChanges.svelte';
 import {fieldValidation} from '$lib/shared/presentation/form-validation';
 import {onMount,tick,untrack} from 'svelte';
 import {page} from '$app/state';
 import type {TeamsGateway} from '../application/teams';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {Team} from '../domain/team';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 let {user,gateway}:{user:Account|null;gateway:TeamsGateway}=$props();const {locale}=useLocale();
 let teams=$state<Team[]>([]),loading=$state(true),busy=$state(false),more=$state(false),error=$state(''),selected=$state(''),reason=$state(''),notice=$state('');
 let inspected=$state<Team|null>(null),teamQuery=$state(''),teamTab=$state<'approved'|'pending'>('approved'),approvedTeams=$state<Team[]>([]),moreApproved=$state(false);
 let appliedHash='';
 $effect(()=>{const hash=page.url.hash;const found=teams.find(team=>team.id===hash.replace('#queue-',''));if(found&&hash!==appliedHash)untrack(()=>{appliedHash=hash;if(guard&&!guard.confirmDiscard())return;teamTab='pending';inspectTrigger=undefined;inspected=found;selected='';reason='';});});
 const displayedTeams=$derived(teamTab==='approved'?approvedTeams:teams);
 function switchTab(value:typeof teamTab){if(busy||(guard&&!guard.confirmDiscard()))return;teamTab=value;inspected=null;selected='';reason='';teamQuery='';}
 async function refreshApproved(){const depth=Math.max(1,Math.ceil(approvedTeams.length/100));await loadApproved();for(let step=1;step<depth&&moreApproved;step++)await loadApproved(true);}
 async function loadApproved(append=false){const batch=await gateway.approved(append?approvedTeams.length:0);approvedTeams=append?[...approvedTeams,...batch]:batch;moreApproved=batch.length===100;}
 const visibleTeams=$derived(displayedTeams.filter(team=>[team.name,team.description,team.slug].some(value=>value.toLocaleLowerCase().includes(teamQuery.trim().toLocaleLowerCase()))));
 let inspectionPanel=$state<HTMLElement>(),requestDialog=$state<HTMLDialogElement>(),mounted=$state(false),teamTabs=$state<HTMLElement>();let inspectTrigger:HTMLButtonElement|undefined;
 $effect(()=>{const request=inspected&&!inspected.approved;const dialog=requestDialog;if(!mounted||!dialog)return;untrack(()=>{if(request&&!dialog.open)dialog.showModal();else if(!request&&dialog.open)dialog.close();});});
 async function inspect(team:Team,trigger:HTMLButtonElement){if(busy)return;if(guard&&!guard.confirmDiscard())return;inspectTrigger=trigger;selected='';reason='';inspected=team;await tick();if(team.approved){inspectionPanel?.focus({preventScroll:true});if(window.innerWidth<1000)inspectionPanel?.scrollIntoView({block:'start'});}}
 async function closeInspection(){if(busy)return;if(guard&&!guard.confirmDiscard())return;requestDialog?.close();inspected=null;selected='';reason='';await tick();if(inspectTrigger?.isConnected)inspectTrigger.focus();else teamTabs?.querySelector<HTMLButtonElement>('button[aria-pressed=true]')?.focus();}
 let guard=$state<{confirmDiscard():boolean}>();
 const dirty=$derived(selected!==''&&reason.trim()!=='');
 async function load(append=false){const batch=await gateway.pending(append?teams.length:0);teams=append?[...teams,...batch]:batch;more=batch.length===100;}
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';try{await action();}catch(failure){error=failureCode(failure);}finally{busy=false;}}
 onMount(()=>{mounted=true;if(user?.role!=='admin'){loading=false;return;}void run(async()=>{try{await load();await loadApproved();if(window.location.hash.startsWith('#queue-'))teamTab='pending';const depth=queueDepth(new URL(window.location.href));for(let step=1;step<depth&&more;step++)await load(true);const wanted=window.location.hash.replace('#queue-','');if(wanted)inspected=teams.find(team=>team.id===wanted)||null;await tick();if(window.location.hash)document.getElementById(window.location.hash.slice(1))?.scrollIntoView();}finally{loading=false;}});});
</script>
{#snippet teamDetails(team:Team)}<article><div class="team-identity"><TeamAvatar id={team.id} name={team.name} size={88}/><h2>{team.name}</h2></div>{#if team.description}<p>{team.description}</p>{/if}<dl class="request-facts"><div><dt>{text($locale,'Күйі','Статус')}</dt><dd>{team.approved?text($locale,'Мақұлданған','Одобрена'):team.reviewStatus==='rejected'?text($locale,'Қайтарылған','Возвращена'):text($locale,'Қаралуда','На рассмотрении')}</dd></div>{#if !team.approved||team.telegramURL}<div><dt>Telegram</dt><dd>{#if team.telegramURL}<a class="auth-link" href={team.telegramURL} target="_blank" rel="noreferrer">{team.telegramURL} ↗</a>{:else}{text($locale,'Көрсетілмеген','Не указан')}{/if}</dd></div>{/if}</dl>{#if team.reviewNote}<section class="review-note"><h3>{text($locale,'Қарау ескертпесі','Примечание к рассмотрению')}</h3><p>{team.reviewNote}</p></section>{/if}<details class="request-technical"><summary>{text($locale,'Техникалық деректер','Технические данные')}</summary><dl><dt>{text($locale,'Команда ID','ID команды')}</dt><dd>{team.id}</dd><dt>{text($locale,'Сілтеме атауы','Имя в ссылке')}</dt><dd>{team.slug}</dd></dl></details>{#if team.approved}<a class="button subtle" href={'/teams/'+encodeURIComponent(team.slug)}>{text($locale,'Команда парақшасы','Страница команды')}</a>{:else}<div class="actions"><button class="button primary" disabled={busy} onclick={()=>{if(selected===team.id&&guard&&!guard.confirmDiscard())return;void run(async()=>{await gateway.approve(team.id);if(selected===team.id){selected='';reason='';}inspected=null;await load();await refreshApproved();notice=text($locale,'Команда мақұлданды.','Команда одобрена.');});}}>{text($locale,'Мақұлдау','Одобрить')}</button><button class="button subtle" disabled={busy} onclick={()=>{if(guard&&!guard.confirmDiscard())return;selected=team.id;reason='';}}>{text($locale,'Түзетуге қайтару','Вернуть на исправление')}</button></div>
 {#if selected===team.id}<form use:fieldValidation={{locale:$locale}} onsubmit={event=>{event.preventDefault();void run(async()=>{await gateway.reject(team.id,reason);selected='';reason='';inspected=null;await load();notice=text($locale,'Өтінім себеппен қайтарылды.','Заявка возвращена с причиной.');});}}><label>{text($locale,'Не түзету керек?','Что нужно исправить?')}<textarea bind:value={reason} required minlength="8" maxlength="2000" rows="3"></textarea></label><div class="actions"><button class="button primary" disabled={busy}>{text($locale,'Себеппен қайтару','Вернуть с причиной')}</button><button type="button" class="button subtle" onclick={()=>{if(guard&&!guard.confirmDiscard())return;selected='';reason='';}}>{text($locale,'Бас тарту','Отмена')}</button></div></form>{/if}{/if}
 </article>{/snippet}
<UnsavedChanges {dirty} bind:this={guard}/>
<svelte:head><title>{text($locale,'Командалар','Команды')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<SectionHeading level={1} title={text($locale,'Командалар','Команды')} description={text($locale,'Жұмыс істейтін командалар мен жаңа өтінімдер.','Действующие команды и новые заявки на рассмотрение.')}/>
{#if user?.role!=='admin'}<p>{text($locale,'Әкімші рұқсаты қажет.','Нужен доступ администратора.')}</p><a class="button primary" href="/login?returnTo=%2Fadmin">{text($locale,'Кіру','Войти')}</a>
{:else}
 {#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if loading}<p role="status">{text($locale,'Өтінімдер жүктелуде…','Загружаем заявки…')}</p>{:else}
 <nav bind:this={teamTabs} class="team-tabs" aria-label={text($locale,'Команда тізімі','Список команд')}><button class:active={teamTab==='approved'} aria-pressed={teamTab==='approved'} disabled={busy} onclick={()=>switchTab('approved')}>{text($locale,'Командалар','Команды')} · {approvedTeams.length}{moreApproved?'+':''}</button><button class:active={teamTab==='pending'} aria-pressed={teamTab==='pending'} disabled={busy} onclick={()=>switchTab('pending')}>{text($locale,'Өтінімдер','Заявки')} · {teams.length}{more?'+':''}</button></nav><div class="team-workbench"><section class="team-list"><label>{text($locale,'Жүктелген командалардан іздеу','Поиск среди загруженных команд')}<input type="search" bind:value={teamQuery} placeholder={text($locale,'Команда атауы','Название команды')}/></label>{#each visibleTeams as team}<article class:chosen={inspected?.id===team.id} id={'queue-'+team.id}><div class="team-identity"><TeamAvatar id={team.id} name={team.name}/><h2>{team.name}</h2></div>{#if team.description}<p>{team.description}</p>{:else if !team.approved}<p>{text($locale,'Сипаттама берілмеген','Описание не указано')}</p>{/if}<div class="team-row-footer"><span>{team.approved?text($locale,'Мақұлданған','Одобрена'):text($locale,'Қаралуда','На рассмотрении')}</span><button class="button subtle" disabled={busy} onclick={event=>void inspect(team,event.currentTarget)}>{team.approved?text($locale,'Команданы ашу','Открыть команду'):text($locale,'Өтінімді ашу','Открыть заявку')} →</button></div></article>{:else}<div class="empty-state"><h2>{teamQuery?text($locale,'Команда табылмады','Команды не найдены'):teamTab==='pending'?text($locale,'Жаңа өтінім жоқ','Новых заявок нет'):text($locale,'Әзірге команда жоқ','Команд пока нет')}</h2><p>{text($locale,'Жоба өтінімдері бөлек бөлімде қаралады.','Заявки на проекты рассматриваются отдельно.')}</p><a class="button subtle" href="/admin/requests">{text($locale,'Жоба өтінімдері','Заявки на проекты')}</a></div>{/each}</section>{#if inspected?.approved}<aside class="team-inspector" bind:this={inspectionPanel} tabindex="-1" aria-label={text($locale,'Команда мәліметтері','Сведения команды')}><button class="button subtle inspector-back" disabled={busy} onclick={()=>void closeInspection()}>{text($locale,'Тізімге оралу','Вернуться к списку')}</button>{@render teamDetails(inspected)}</aside>{/if}</div>
 {#if teamTab==='pending'?more:moreApproved}<button class="button subtle" disabled={busy} onclick={()=>run(()=>teamTab==='pending'?load(true):loadApproved(true))}>{text($locale,'Тағы өтінімдер','Ещё заявки')}</button>{/if}
 {/if}
{/if}
<dialog class="team-inspector team-request-dialog" bind:this={requestDialog} aria-labelledby="team-request-title" oncancel={event=>{event.preventDefault();void closeInspection();}}><header class="request-dialog-heading"><h2 id="team-request-title">{text($locale,'Команда өтінімі','Заявка команды')}</h2><button type="button" class="button subtle dialog-close" disabled={busy} aria-label={text($locale,'Жабу','Закрыть')} onclick={()=>void closeInspection()}>×</button></header>{#if inspected&&!inspected.approved}{#if error}<p role="alert" class="form-message">{noticeText($locale,error)}</p>{/if}{@render teamDetails(inspected)}{/if}</dialog>
<style>.team-identity{display:flex;align-items:center;gap:12px;min-width:0}.team-identity h2{overflow-wrap:anywhere;min-width:0}.team-inspector>article>.button{margin-top:16px}article{max-width:840px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel);margin-block:12px;min-width:0}h2{font-size:20px;margin:0}p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}form{max-width:640px;margin-top:20px}label{display:grid;gap:8px}.team-tabs{margin-bottom:20px;display:flex;gap:8px;flex-wrap:wrap}.team-tabs button{border:1px solid transparent;background:none;color:var(--muted);cursor:pointer}.team-tabs button.active{background:var(--raised);color:var(--accent)}.team-tabs button{display:inline-flex;align-items:center;min-height:44px;padding:8px 16px;border-radius:8px;font-size:13px}.team-workbench{display:grid;gap:24px;align-items:start}.team-list,.team-inspector{min-width:0}.team-list>label{font-size:12px;color:var(--muted);margin-bottom:16px}.team-list article{max-width:none;padding:20px 24px;margin:0 0 16px}.team-list h2,.team-inspector h2{font-size:17px}.team-list article.chosen{background:var(--raised);border-color:var(--muted)}.team-list article.chosen h2{color:var(--accent)}.team-list article p{font-size:13px;color:var(--muted);margin:12px 0}.team-row-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.team-row-footer .button{background:none;border-color:transparent;font-size:12px}.team-inspector article{max-width:none;margin:0;padding:24px}.team-inspector p{font-size:13px;color:var(--muted);margin-top:16px}.team-inspector form{margin-top:20px}.team-inspector .actions{gap:8px}.team-inspector .button{font-size:12px}.team-inspector:empty{display:none}@media(min-width:1000px){.team-workbench{grid-template-columns:minmax(0,2fr) minmax(280px,1fr)}.team-workbench:not(:has(.team-inspector article)){grid-template-columns:minmax(0,1fr)}.team-inspector{position:sticky;top:88px}} .inspector-back{margin-bottom:12px}.team-inspector{scroll-margin-top:80px}@media(min-width:1000px){.inspector-back{display:none}}.team-request-dialog{position:fixed;inset:0;margin:auto;width:min(640px,calc(100vw - 32px));height:fit-content;max-height:calc(100dvh - 32px);overflow:auto;overscroll-behavior:contain;padding:0;border:1px solid var(--line);border-radius:16px;background:var(--panel);color:var(--text);box-shadow:0 24px 80px #0006}.team-request-dialog::backdrop{background:#0009}.team-request-dialog .request-dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 24px;border-bottom:1px solid var(--line)}.request-dialog-heading h2{font-size:17px}.dialog-close{padding:0;min-width:44px;min-height:44px;font-size:26px;background:none}.team-request-dialog article{border:0;border-radius:0}.team-request-dialog>.form-message{margin:16px 24px 0}.request-facts{display:grid;gap:12px;margin:20px 0;font-size:13px}.request-facts>div{display:grid;grid-template-columns:90px minmax(0,1fr);gap:12px}.request-facts dt,.request-technical dt{color:var(--muted)}.request-facts dd,.request-technical dd{margin:0;overflow-wrap:anywhere}.request-facts a{display:inline-flex;align-items:center;min-height:44px}.request-technical{margin-top:16px;font-size:12px}.request-technical summary{min-height:44px;display:flex;align-items:center;cursor:pointer;color:var(--muted)}.request-technical dl{display:grid;gap:8px;padding:12px;background:var(--raised);border-radius:8px}.review-note h3{font-size:13px;margin-top:20px}.team-request-dialog .team-identity h2{font-size:20px}@media(max-width:420px){.team-request-dialog{width:calc(100vw - 16px);max-height:calc(100dvh - 16px)}.team-request-dialog article{padding:16px}.team-request-dialog .request-dialog-heading{padding:12px 16px}}
</style>
